            node->left = new TreeNode(stoll(vals[i]));
            queue.push_back(node->left);
        }
        i++;
        if (i < vals.size() && vals[i] != "N") {
            node->right = new TreeNode(stoll(vals[i]));
            queue.push_back(node->right);
        }
        i++;
    }
    return root;
